var shinCustomBack=flowBack;
flowBack=function(id){
 if(!SHIN_BACK_ART[id])return shinCustomBack(id);
 var x=HMAP[id],pv=x.prov||x.jp,old=document.createElement('div');old.innerHTML=shinCustomBack(id);var story=old.querySelector('.flow-senpai');
 return '<article class="flow-paper flow-back shin-art-back">'+shinBackArt(id)+'<div class="shin-back-copy"><small class="shin-back-label">Ý NGHĨA · 意味</small><h2>'+esc(hname(id))+'</h2><div class="shin-back-proverb"><p lang="ja">'+esc(pv.j)+'</p><button class="flow-card-speak" data-act="speak" data-v="'+esc(pv.j)+'" aria-label="Nghe câu tiếng Nhật">'+mi('volume_up')+'</button></div><p class="shin-back-romaji">'+esc(pv.r)+'</p><p class="shin-back-meaning">'+esc(pv.v)+'</p><p class="shin-back-benefit">'+esc(BEN[id]||(x.why||{}).now||'')+'</p>'+(story?story.outerHTML:'')+'</div></article>';
};
function shinActivePaper(root){return (root||document).querySelector('.shin-card-face:not([inert]) .flow-paper')||(root||document).querySelector('.flow-paper');}
function shinCardFaces(id,back){
 if(window.SHIN_FLIP_ANIMATION){window.SHIN_FLIP_ANIMATION.cancel();window.SHIN_FLIP_ANIMATION=null;EVENING_FLIPPING=false;}
 return '<div class="shin-card-turner" style="transform:rotateY('+(back?180:0)+'deg)"><div class="shin-card-face shin-card-front"'+(back?' inert aria-hidden="true"':'')+'>'+flowFront(id)+'</div><div class="shin-card-face shin-card-back"'+(!back?' inert aria-hidden="true"':'')+'>'+flowBack(id)+'</div></div>';
}

