function m3HabitSvg(k){return '<svg viewBox="0 0 24 24" aria-hidden="true"><g transform="translate(0 24) scale(.025)"><path fill="currentColor" d="'+M3HI_PATHS[m3HabitKey(k)]+'"/></g></svg>';}
function m3HabitGroup(id){var x=HMAP[id];return x?(x.g||5):1;}
function m3HabitBadge(id){return '<span class="m3hi g'+m3HabitGroup(id)+'">'+m3HabitSvg(id)+'</span>';}
